/**
 * Functor for tokens.
 */
final class TokenFunctor[A](private val _value: A) {
  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(f(_value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] = f(_value)

  def getOrElse(default: => A): A = Option(_value).getOrElse(default)

  def get: A = _value
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
 */
final class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(this.get))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)

  def apply[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

