// JSON Structure Tokenization
// ============================================================================

/**
 * Represents JSON values using a sealed trait hierarchy.
 */
sealed trait JsonValue

object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  def fromAny(value: Any): JsonValue = value match {
    case null       => JsonNull
    case s: String  => JsonString(s)
    case i: Int     => JsonNumber(BigDecimal(i))
    case l: Long    => JsonNumber(BigDecimal(l))
    case d: Double  => JsonNumber(BigDecimal(d))
    case f: Float   => JsonNumber(BigDecimal(f.toDouble))
    case bd: BigDecimal => JsonNumber(bd)
    case b: Boolean => JsonBoolean(b)
    case arr: Seq[_] => JsonArray(arr.map(fromAny).toVector)
    case m: Map[_, _] =>
      JsonObject(m.map { case (k, v) => k.toString -> fromAny(v) }.toMap)
    case _ => JsonString(value.toString)
  }
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
final class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) toJsonStringPretty(value, 0) else toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    extractPath(value, parts).map(tokenize)
  }

  private def extractPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case JsonObject(fields) =>
          fields.get(head).flatMap(v => extractPath(v, tail))
        case JsonArray(values) =>
          Try(head.toInt).toOption
            .filter(idx => idx >= 0 && idx < values.length)
            .flatMap(idx => extractPath(values(idx), tail))
        case _ => None
      }
  }

  private def toJsonString(value: JsonValue): String = value match {
    case JsonString(s)   => s""""${escapeJsonString(s)}""""
    case JsonNumber(n)   => n.toString()
    case JsonBoolean(b)  => b.toString
    case JsonNull        => "null"
    case JsonArray(arr)  => arr.map(toJsonString).mkString("[", ", ", "]")
    case JsonObject(obj) =>
      obj.map { case (k, v) => s""""${escapeJsonString(k)}": ${toJsonString(v)}""" }
        .mkString("{", ", ", "}")
  }

  private def toJsonStringPretty(value: JsonValue, indent: Int): String = {
    val pad = "  " * indent
    val padInner = "  " * (indent + 1)
    value match {
      case JsonString(s)   => s""""${escapeJsonString(s)}""""
      case JsonNumber(n)   => n.toString()
      case JsonBoolean(b)  => b.toString
      case JsonNull        => "null"
      case JsonArray(arr) if arr.isEmpty => "[]"
      case JsonArray(arr)  =>
        arr.map(v => padInner + toJsonStringPretty(v, indent + 1))
          .mkString("[\n", ",\n", s"\n$pad]")
      case JsonObject(obj) if obj.isEmpty => "{}"
      case JsonObject(obj) =>
        obj.map { case (k, v) =>
          s"""$padInner"${escapeJsonString(k)}": ${toJsonStringPretty(v, indent + 1)}"""
        }.mkString("{\n", ",\n", s"\n$pad}")
    }
  }

  private def escapeJsonString(s: String): String =
    s.flatMap {
      case '"'  => "\\\""
      case '\\' => "\\\\"
      case '\n' => "\\n"
      case '\r' => "\\r"
      case '\t' => "\\t"
      case c    => c.toString
    }
}

object JsonTokenizer {
  def apply(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * This is a fundamental tokenization operation used in NLP and text processing.
 */
final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = if (stripPunctuation) {
      word.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    } else word

    processed = if (lowercase) processed.toLowerCase else processed

    if (processed.length < minLength) return None

    processed = maxLength match {
      case Some(max) if processed.length > max => processed.take(max)
      case _ => processed
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    val result = mutable.ListBuffer[(String, Int, Int)]()

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

object WhitespaceTokenizer {
  def apply(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

